import { execSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { gzipSync } from "node:zlib";
import { describe, expect, it } from "vitest";

const distDir = resolve(import.meta.dirname, "../../dist");

describe("answer page performance budget", () => {
  it("satisfies HTML, CSS, and JS critical path budgets", () => {
    const htmlPath = resolve(distDir, "answer.html");
    if (!existsSync(htmlPath)) {
      execSync("pnpm --filter @surveybeat/web build", {
        cwd: resolve(import.meta.dirname, "../../../.."),
        stdio: "ignore",
      });
    }
    expect(existsSync(htmlPath), "apps/web/dist/answer.html should exist").toBe(true);

    const html = readFileSync(htmlPath, "utf8");
    const htmlGz = gzipSync(Buffer.from(html), { level: 9 }).length;

    // Budget: HTML ≤ 8 KB (raw and gzip)
    expect(
      html.length,
      `HTML raw size (${(html.length / 1024).toFixed(2)} KB) should be ≤ 8 KB`,
    ).toBeLessThanOrEqual(8 * 1024);
    expect(htmlGz, `HTML gzip size (${(htmlGz / 1024).toFixed(2)} KB) should be ≤ 8 KB`).toBeLessThanOrEqual(
      8 * 1024,
    );

    // Budget: CSS ≤ 2 KB inline (measured as gzip in prototype RESULTS.md, raw also kept minimal)
    const styleMatch = html.match(/<style>([\s\S]*?)<\/style>/);
    expect(styleMatch, "answer.html should have inline <style>").not.toBeNull();
    const inlineCss = styleMatch ? (styleMatch[1] ?? "") : "";
    const inlineCssGz = gzipSync(Buffer.from(inlineCss), { level: 9 }).length;
    expect(
      inlineCssGz,
      `Inline CSS gzip size (${(inlineCssGz / 1024).toFixed(2)} KB) should be ≤ 2 KB`,
    ).toBeLessThanOrEqual(2 * 1024);

    // Budget: JS ≤ 10 KB gzip on critical path
    const scriptSrcMatches = Array.from(html.matchAll(/<script\b[^>]*src="([^"]+)"[^>]*>/g)).map(
      (m) => m[1] ?? "",
    );
    expect(scriptSrcMatches.length).toBeGreaterThan(0);

    const assetsDir = resolve(distDir, "assets");
    let criticalPathJsGz = 0;

    const allAssetFiles = readdirSync(assetsDir);
    for (const src of scriptSrcMatches) {
      const fileName = src.split("/").pop();
      if (fileName && fileName.endsWith(".js") && existsSync(resolve(assetsDir, fileName))) {
        const fileContent = readFileSync(resolve(assetsDir, fileName));
        criticalPathJsGz += gzipSync(fileContent, { level: 9 }).length;
      }
    }

    for (const f of allAssetFiles) {
      if (f.startsWith("messages-") && f.endsWith(".js")) {
        const fileContent = readFileSync(resolve(assetsDir, f));
        criticalPathJsGz += gzipSync(fileContent, { level: 9 }).length;
      }
    }

    expect(
      criticalPathJsGz,
      `Critical path JS (${(criticalPathJsGz / 1024).toFixed(2)} KB gzip) should be ≤ 10 KB gzip`,
    ).toBeLessThanOrEqual(10 * 1024);
  });
});
import { catalog } from "./catalog.ts";

type Catalog = typeof catalog;
export type MessageKey = keyof Catalog;
type Value = string | number;

type Placeholders<T extends string> = T extends `${string}{${infer Name}}${infer Rest}`
  ? Name | Placeholders<Rest>
  : never;
type Params<K extends MessageKey> = Readonly<Record<Placeholders<Catalog[K]>, Value>>;
type KeysWithoutParams = {
  [K in MessageKey]: [Placeholders<Catalog[K]>] extends [never] ? K : never;
}[MessageKey];
type KeysWithParams = Exclude<MessageKey, KeysWithoutParams>;

type PluralBase<K extends string> = K extends `${infer Base}.other` ? Base : never;
export type PluralKey = PluralBase<MessageKey>;
type PluralParams<B extends PluralKey> = Readonly<
  Record<Exclude<Placeholders<Catalog[`${B}.other`]>, "count">, Value>
>;

const LOCALE = "en";
let cachedPluralRules: Intl.PluralRules | undefined;
function getPluralRules(): Intl.PluralRules {
  if (!cachedPluralRules) {
    cachedPluralRules = new Intl.PluralRules(LOCALE);
  }
  return cachedPluralRules;
}

const isMessageKey = (key: string): key is MessageKey => Object.hasOwn(catalog, key);

function fill(template: string, params: Readonly<Record<string, Value>>): string {
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? ""));
}

/** Looks up a message; placeholders are checked against the template at compile time. */
export function message<K extends KeysWithoutParams>(key: K): string;
export function message<K extends KeysWithParams>(key: K, params: Params<K>): string;
export function message(key: MessageKey, params: Readonly<Record<string, Value>> = {}): string {
  return fill(catalog[key], params);
}

/** Picks the plural form for `count` with `Intl.PluralRules`; `{count}` is filled in. */
export function pluralMessage<B extends PluralKey>(base: B, count: number, params?: PluralParams<B>): string {
  const specific = `${base}.${getPluralRules().select(count)}`;
  const template = isMessageKey(specific) ? catalog[specific] : catalog[`${base}.other`];
  return fill(template, { ...params, count: new Intl.NumberFormat(LOCALE).format(count) });
}

/** Formats a date for display with `Intl.DateTimeFormat`. */
export function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" },
): string {
  return new Intl.DateTimeFormat(LOCALE, options).format(date);
}
